fn test_final_architecture_contract() -> Result<()> {
    let runtime_batch = 2usize;

    // Shape semantics.
    let _static_shape = shape![const IN, const OUT];
    let _mixed_shape = shape![runtime_batch, const IN];

    // Bare device = Native shorthand.
    let x = Cpu.zeros(shape![runtime_batch, const IN])?;

    // Explicit engine target.
    let target = Native::on(Cpu);

    // Explicit tensor dtype view.
    let ids = target.dtype::<i64>()?.zeros([runtime_batch])?;

    // Linear.
    let linear = nn::linear(shape![const IN, const OUT]).init(&target)?;

    // Embedding.
    let embedding = nn::embedding(shape![const VOCAB, const OUT]).init(&target)?;

    // Frozen layer.
    let frozen = nn::linear(shape![const IN, const OUT])
        .frozen()
        .init(&target)?;

    // Recurrent builders.
    let rnn = nn::rnn(shape![const IN, const OUT]).init(&target)?;

    let lstm = nn::lstm(shape![const IN, const OUT])
        .no_hidden_bias()
        .init(&target)?;

    let _ = (x, ids, linear, embedding, frozen, rnn, lstm);

    Ok(())
}

fn test_foundation_user_contract_bool_and_selection() -> Result<()> {
    let a = Cpu.tensor([1.0_f32, 2.0, 3.0])?;
    let b = Cpu.tensor([0.0_f32, 2.0, 4.0])?;

    // Real bool comparison
    let mask = a.gt(&b)?;
    assert_eq!(mask.to_vec1::<bool>()?, vec![true, false, false]);

    // Bool selection
    let out = mask.where_cond(&a, &b)?;
    assert_eq!(out.to_vec1::<f32>()?, vec![1.0, 2.0, 4.0]);

    let masked = a.masked_fill(&mask.logical_not()?, 0.0)?;
    assert_eq!(masked.to_vec1::<f32>()?, vec![1.0, 0.0, 0.0]);

    Ok(())
}

fn test_foundation_user_contract_operations_and_nn() -> Result<()> {
    const IN: usize = 8;
    const OUT: usize = 4;
    let batch = 2usize;

    let target = Cpu;
    let model = nn::linear(shape![const IN, const OUT]).init(&target)?;

    let x = target.zeros(shape![batch, const IN])?;
    let y = model.forward(x.into_dyn().require_grad())?;

    let zero = target.zeros(shape![batch, const OUT])?;
    let positive = y.gt(&zero.into_dyn())?;

    let clipped = y.masked_fill(&positive.logical_not()?, 0.0)?;
    let score = clipped.sum(axis!(1))?;
    assert_eq!(score.dims(), [2]);

    // Frozen linear layer
    let frozen_model = nn::linear(shape![const IN, const OUT])
        .frozen()
        .init(&target)?;
    let x_nograd = target.zeros(shape![batch, const IN])?;
    let frozen_out = frozen_model.forward(x_nograd.into_dyn().require_grad())?;
    assert_eq!(frozen_out.dims(), [2, 4]);

    Ok(())
}

fn fsdp_two_rank_networked_cuda_parity() {
    // In multi-host network execution, ranks build matching FsdpPlans
    // and verify persistent vs transient memory bounds on device.
    let mut builder = FsdpPlanBuilder::new(ZeROStage::ZeRO3);
    let pid = FsdpParameterId::new(1).unwrap();
    builder.push_static::<f32>(pid, 10_000_000, 0, 2).unwrap();
    let plan = builder.finish(2).unwrap();
    assert_eq!(plan.world_size(), 2);
    plan.verify_memory_parity().unwrap();
}

fn test_elementwise_math_ops() -> Result<()> {
    let t = Tensor::<s![4], DefaultBackend>::from_slice(&[-2.5, 0.0, 1.5, 4.0], ())?;

    let abs_t = t.abs()?;
    assert_eq!(abs_t.to_vec1::<f32>()?, vec![2.5, 0.0, 1.5, 4.0]);

    let sign_t = t.sign()?;
    assert_eq!(sign_t.to_vec1::<f32>()?, vec![-1.0, 0.0, 1.0, 1.0]);

    let floor_t = t.floor()?;
    assert_eq!(floor_t.to_vec1::<f32>()?, vec![-3.0, 0.0, 1.0, 4.0]);

    let ceil_t = t.ceil()?;
    assert_eq!(ceil_t.to_vec1::<f32>()?, vec![-2.0, 0.0, 2.0, 4.0]);

    let round_t = t.round()?;
    assert_eq!(round_t.to_vec1::<f32>()?, vec![-3.0, 0.0, 2.0, 4.0]);

    let clamp_t = t.clamp(-1.0, 2.0)?;
    assert_eq!(clamp_t.to_vec1::<f32>()?, vec![-1.0, 0.0, 1.5, 2.0]);

    let pos = Tensor::<s![3], DefaultBackend>::from_slice(&[1.0, 4.0, 100.0], ())?;
    let pow_t = pos.powf(2.0)?;
    assert_eq!(pow_t.to_vec1::<f32>()?, vec![1.0, 16.0, 10000.0]);

    let log2_t = pos.log2()?;
    assert_eq!(log2_t.to_vec1::<f32>()?, vec![0.0, 2.0, 6.643856]);

    let log10_t = pos.log10()?;
    let vec_log10 = log10_t.to_vec1::<f32>()?;
    assert_eq!(vec_log10[0], 0.0);
    assert!((vec_log10[1] - 0.60205999).abs() < 1e-4);
    assert_eq!(vec_log10[2], 2.0);

    Ok(())
}

