fn a_union_row_is_posed_at_the_catalog_floor_as_well_as_its_own() {
    use incin_backends::conformance::advertised_tuples;
    use incin_core::shapes::error::OperationKind;
    use incin_core::tensor::device::DeviceKind;

    let ranks = |operation: OperationKind| -> BTreeSet<usize> {
        advertised_tuples(DeviceKind::Cpu)
            .into_iter()
            .filter(|tuple| tuple.operation == operation)
            .map(|tuple| tuple.rank)
            .collect()
    };

    // `accepted_ranks` is 3..=4 for the two-dimensional convolutions and 2..=3
    // for `conv1d`, against a declared floor of one in all three.
    assert_eq!(
        ranks(OperationKind::Conv2dExact),
        BTreeSet::from([1, 3, 4]),
        "conv2d must be posed at the activation's floor, not only at the row's"
    );
    assert_eq!(ranks(OperationKind::Conv1dExact), BTreeSet::from([1, 2, 3]));
    assert_eq!(
        ranks(OperationKind::ConvTranspose2d),
        BTreeSet::from([1, 3, 4])
    );

    // A row that agrees with the catalog keeps two boundaries. `batch_norm` is
    // a union row too, but the tighter floor its activation needs is enforced
    // inside `BatchNormAttributes::validate` rather than declared in
    // `accepted_ranks`, so there is nothing here for the enumeration to read.
    assert_eq!(ranks(OperationKind::BatchNorm), BTreeSet::from([1, 4]));
    assert_eq!(ranks(OperationKind::Relu), BTreeSet::from([0, 4]));
}

fn blocking_reason(operation: OperationKind) -> Option<&'static str> {
    Some(match operation {
        OperationKind::Sample => {
            "`DistributionAttributes` names its distribution as a string and its \
             parameters as bytes. Executing one needs a registry that maps that pair \
             back to a sampler, and no such registry exists"
        }
        OperationKind::Rnn | OperationKind::Lstm => {
            "the descriptor carries no weights. Its operand arity admits an input and \
             the recurrent states only, and `RecurrentAttributes` holds sizes and \
             bias-presence flags, so the matrices the recurrence multiplies by cannot \
             be named"
        }
        _ => return None,
    })
}

fn close(left: f64, right: f64) -> bool {
    (left - right).abs() <= 1e-5 * left.abs().max(right.abs()).max(1.0)
}

fn embedding_gathers_the_rows_its_indices_name() {
    require_cuda();
    let (shape, values) = weight();
    let w = upload_f32_shaped(&shape, &values);
    let ids = [2_i64, 0, 3, 2];
    let indices = upload_i64(&[ids.len()], &ids);

    let out = embedding(&w, &indices).expect("embedding must launch");
    assert_eq!(&out.shape[..], &[4, 3], "one row of width 3 per index");
    let got = download_f32(&out);

    for (position, id) in ids.iter().enumerate() {
        for column in 0..3usize {
            let expected = values[usize::try_from(*id).unwrap() * 3 + column];
            assert!(
                close(f64::from(got[position * 3 + column]), f64::from(expected)),
                "row {position} (index {id}) column {column}: kernel gave {}, table has {expected}",
                got[position * 3 + column]
            );
        }
    }
}

fn storage(shape: &[usize], values: &[f32]) -> TestStorage {
    TestBackend::from_bytes::<f32>(
        bytemuck::cast_slice(values),
        shape,
        DTypeId::F32.into(),
        &DeviceId::cuda(0),
    )
    .expect("test buffer must match its shape")
}

fn read(storage: &TestStorage) -> Vec<f32> {
    let bytes = TestBackend::to_bytes::<f32>(storage).expect("readback must succeed");
    bytemuck::cast_slice(&bytes).to_vec()
}

fn execute_one<O>(
    validated: &Validated<Descriptor<O>>,
    input: &TestStorage,
) -> Result<TestStorage, BackendError>
where
    O: CanonicalOperation,
    O::Attributes: AttributeContract,
    TestBackend: Execute<O, Output = TestStorage>,
{
    let context = ExecutionContext::new(TestBackend::new());
    let inputs = [TensorHandle::from_storage::<TestBackend, f32, Local>(input)];
    context.backend().execute(ExecutionRequest {
        operation: validated,
        inputs: &inputs,
        context: &context,
        payload: None,
    })
}

fn cuda_reduction_descriptor_routes_to_the_accumulation_it_names() {
    require_cuda();
    let input = storage(&[2, 3], &[1., 2., 3., 4., 5., 6.]);

