    let input = storage(&[1, 1, 4, 4], &values);

    macro_rules! check {
        ($marker:ty, $expected:expr) => {{
            let validated = Descriptor::<$marker>::infer_runtime(
                Pool2dAttributes {
                    kernel: [2, 2],
                    stride: [2, 2],
                    padding: [0, 0],
                    dilation: [1, 1],
