fn a_cuda_matmul_is_dense_and_refuses_a_strided_operand() {
    incin_backends::cuda::testing::require_cuda();

    let lhs = Tensor::<s![4, 3], Cuda>::from_slice(
        &[
            1.0f32, 5.0, 9.0, 2.0, 6.0, 10.0, 3.0, 7.0, 11.0, 4.0, 8.0, 12.0,
        ],
        (),
    )
    .unwrap();
    let rhs = Tensor::<s![3, 2], Cuda>::ones(()).unwrap();

    let product = lhs.matmul(&rhs).unwrap();
    assert_dense("matmul", &product);
    assert_eq!(
        product.to_vec1::<f32>().unwrap(),
        alloc_vec(&[15.0, 15.0, 18.0, 18.0, 21.0, 21.0, 24.0, 24.0]),
        "the same product the CPU test checks, so the two backends are \
         compared against one answer rather than each against itself"
    );

    let bias = Tensor::<s![4, 2], Cuda>::ones(()).unwrap();
    assert_dense("addmm", &bias.addmm(&lhs, &rhs, 1.0, 1.0).unwrap());

    // A strided operand: refused, not silently multiplied wrongly.
    let base = Tensor::<s![3, 4], Cuda>::ones(()).unwrap();
    let strided = base
        .transpose_view::<Here, Next<Here>>()
        .expect("a 3x4 tensor transposes to 4x3");
    assert!(
        strided.matmul(&rhs).is_err(),
        "CUDA advertises only contiguous matmul layouts, so a strided operand \
         must be refused; if this now succeeds the capability row changed and \
         the RowMajor claim needs re-earning"
    );
}

fn sgd_step_matches_the_update_rule() {
    require_cuda();
    let (p, g) = (params(), grads());
    let learning_rate = 0.1;

    let out = incin_backends::cuda::testing::sgd_step(
        &upload_f32(&p),
        &upload_f32(&g),
        &SgdAttributes { learning_rate },
    )
    .expect("sgd_step must launch");
    let got = download_f32(&out);

    for index in 0..p.len() {
        let expected = f64::from(p[index]) - learning_rate * f64::from(g[index]);
        assert!(
            close(f64::from(got[index]), expected),
            "sgd at {index}: kernel gave {}, rule gives {expected}",
            got[index]
        );
    }
}

fn adam_step_matches_the_update_rule_including_bias_correction() {
    require_cuda();
    let (p, g) = (params(), grads());
    let attrs = AdamAttributes {
        learning_rate: 1e-3,
        beta1: 0.9,
        beta2: 0.999,
        epsilon: 1e-8,
        step: 1,
    };

    let (p_out, m_out, v_out) = incin_backends::cuda::testing::adam_step(
        &upload_f32(&p),
        &upload_f32(&g),
        None,
        None,
        &attrs,
    )
    .expect("adam_step must launch");
    let (got_p, got_m, got_v) = (
        download_f32(&p_out),
        download_f32(&m_out),
        download_f32(&v_out),
    );

    let bias1 = 1.0 - attrs.beta1.powi(attrs.step as i32);
    let bias2 = 1.0 - attrs.beta2.powi(attrs.step as i32);
    for index in 0..p.len() {
        let grad = f64::from(g[index]);
        let m = (1.0 - attrs.beta1) * grad;
        let v = (1.0 - attrs.beta2) * grad * grad;
        let expected = f64::from(p[index])
            - attrs.learning_rate * ((m / bias1) / ((v / bias2).sqrt() + attrs.epsilon));

        assert!(close(f64::from(got_m[index]), m), "adam m at {index}");
        assert!(close(f64::from(got_v[index]), v), "adam v at {index}");
        assert!(
            close(f64::from(got_p[index]), expected),
            "adam p at {index}: kernel gave {}, rule gives {expected}",
            got_p[index]
        );
    }
}

fn argmax_and_argmin_return_positions() {
    require_cuda();
    let (shape, values) = matrix();
    let input = upload_f32_shaped(&shape, &values);

    // row 0: [3, 1, 4, 1.5] -> max at 2, min at 1
    // row 1: [-2, 5, 0.5, -3] -> max at 1, min at 3
    let max_idx = download_i64(&argmax_argmin("argmax", &input, Some(1)).expect("argmax launches"));
    let min_idx = download_i64(&argmax_argmin("argmin", &input, Some(1)).expect("argmin launches"));

    assert_eq!(max_idx, vec![2, 1], "argmax positions");
    assert_eq!(min_idx, vec![1, 3], "argmin positions");
}

fn topk_returns_ordered_values_and_their_indices() {
    require_cuda();
    let (shape, values) = matrix();
    let input = upload_f32_shaped(&shape, &values);

    let (vals, idx) = topk(&input, 2, 1, true).expect("topk launches");
    let (vals, idx) = (download_f32(&vals), download_i64(&idx));

    // row 0: [3, 1, 4, 1.5] -> 4 at 2, then 3 at 0
    // row 1: [-2, 5, 0.5, -3] -> 5 at 1, then 0.5 at 2
    assert!(close(f64::from(vals[0]), 4.0) && close(f64::from(vals[1]), 3.0));
    assert!(close(f64::from(vals[2]), 5.0) && close(f64::from(vals[3]), 0.5));
    assert_eq!(idx, vec![2, 0, 1, 2], "topk indices");

    // The indices must actually address the values returned beside them.
    for (position, index) in idx.iter().enumerate() {
        let row = position / 2;
        let source = values[row * 4 + usize::try_from(*index).unwrap()];
        assert!(
            close(f64::from(vals[position]), f64::from(source)),
            "topk index {index} does not point at the value it was returned with"
        );
    }
}

fn transpose_is_its_own_inverse() {
    require_cuda();
    let (dims, values) = matrix();
    let source = upload_f32_shaped(&dims, &values);

    let there = transpose(&source, 0, 1).expect("first transpose");
    let back = transpose(&there, 0, 1).expect("second transpose");

    assert_eq!(&back.shape[..], &[2, 3]);
    assert_eq!(
