fn test_simd_lanes_positive_and_divisible() {
    let lanes_f32 = simd_lanes::<f32>();
    let lanes_f64 = simd_lanes::<f64>();
    let lanes_f16 = simd_lanes::<f16>();
    let lanes_bf16 = simd_lanes::<bf16>();
